 @Container static final PostgreSQLContainer DB=new PostgreSQLContainer(DockerImageName.parse("postgres@sha256:74935e72241653ca55e0414067e6d8763aceb8a810eb51b452253ec3dcfc4336").asCompatibleSubstituteFor("postgres"));
 static final Instant NOW=Instant.parse("2026-10-22T12:00:00Z");static JdbcTemplate owner,http,executor;static TransactionTemplate ownerTx,httpTx;static final ResourceRevisions REVISIONS=new ResourceRevisions(new byte[32]);
 static class MutableClock extends Clock{Instant at=NOW;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId ignored){return this;}public Instant instant(){return at;}}
 final MutableClock clock=new MutableClock();final UuidGenerator ids=new UuidGenerator(clock);JdbcPrivateCaseReview review;JdbcScopedRedactions service;JdbcCaseDispositions dispositions;
 @BeforeAll static void migrate()throws Exception{
  MigrationCommand.migrate(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());var base=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());owner=new JdbcTemplate(base);ownerTx=new TransactionTemplate(new DataSourceTransactionManager(base));owner.execute("CREATE ROLE scoped_http NOLOGIN");owner.execute("CREATE ROLE scoped_executor NOLOGIN");owner.execute("GRANT USAGE ON SCHEMA public TO scoped_http");owner.execute("GRANT SELECT ON account_identity,platform_account,application_session,application_session_identity,organization,privacy_case_metadata TO scoped_http");owner.execute("GRANT UPDATE(id) ON account_identity,application_session,organization TO scoped_http");owner.execute("GRANT INSERT ON audit_event TO scoped_http");for(String f:List.of("private-review-grants.sql","scoped-redaction-http-grants.sql","privacy-fulfillment-grants.sql","case-disposition-http-grants.sql"))owner.execute(java.nio.file.Files.readString(java.nio.file.Path.of("audit",f)).replace("__RUNTIME_ROLE__","scoped_http"));owner.execute(java.nio.file.Files.readString(java.nio.file.Path.of("audit/scoped-redaction-worker-grants.sql")).replace("__EXECUTOR_ROLE__","scoped_executor"));owner.update("INSERT INTO privacy_redaction_executor(id,revision,role_oid,environment_code,enabled,configuration_reference,created_at,updated_at) SELECT 1,1,oid,'SYNTHETIC',true,'SYN-SCOPED',?,? FROM pg_roles WHERE rolname='scoped_executor'",Timestamp.from(NOW),Timestamp.from(NOW));
  http=role(base,"scoped_http");executor=role(base,"scoped_executor");httpTx=new TransactionTemplate(new DataSourceTransactionManager(http.getDataSource()));httpTx.setTimeout(10);
 }
 static JdbcTemplate role(DriverManagerDataSource base,String role){return new JdbcTemplate(new DelegatingDataSource(base){@Override public Connection getConnection()throws SQLException{var c=super.getConnection();try(var s=c.createStatement()){s.execute("SET ROLE "+role);s.execute("SET TIME ZONE 'Europe/Belgrade'");s.execute("SET lock_timeout='2s'");s.execute("SET statement_timeout='10s'");}return c;}});}
 @BeforeEach void services(){review=new JdbcPrivateCaseReview(http,clock,ids);@SuppressWarnings("unchecked") ObjectProvider<ResourceRevisions> revisions=mock(ObjectProvider.class);when(revisions.getObject()).thenReturn(REVISIONS);service=new JdbcScopedRedactions(http,review,revisions,clock,ids);dispositions=new JdbcCaseDispositions(http,review,revisions,clock,ids);}
 record Fixture(UUID source,UUID organization,String country,UUID subject,UUID owner,PrivateCaseReview.Actor actor){}
 Fixture fixture(String country,String type,String role){UUID source=ids.next(),org=ids.next(),subject=ids.next(),ownerId=role.equals("OWNER")?subject:ids.next(),operator=ids.next(),session=ids.next();ownerTx.executeWithoutResult(s->{for(UUID id:new LinkedHashSet<>(List.of(subject,ownerId,operator)))owner.update("INSERT INTO account_identity(id,kind,email,email_verified,display_name,state,created_at,updated_at) VALUES(?,?,?,true,'PRIVATE-DISPLAY-ČAJ','ACTIVE',?,?)",id,id.equals(operator)?"PLATFORM_ADMIN":"BUSINESS",id+"@example.com",at(),at());owner.update("INSERT INTO platform_account(id) VALUES(?)",operator);owner.update("INSERT INTO organization(id,type,country,currency,display_name,legal_name,registration_identifier,address_line1,address_city,address_postal_code,address_country,default_language,state,owner_account_id) VALUES(?,?,?,?,'Synthetic','Synthetic',?,'Synthetic','Synthetic','11000',?,'en','ACTIVE',?)",org,type,country,country.equals("RS")?"RSD":"BAM",org.toString(),country,ownerId);owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,'OWNER')",ownerId,org);if(!subject.equals(ownerId))owner.update("INSERT INTO business_account(id,organization_id,role) VALUES(?,?,?)",subject,org,role);owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-SCOPED'");owner.update("INSERT INTO privacy_operator(account_id,created_at) VALUES(?,?)",operator,at());owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',sha256(convert_to(?,'UTF8')),'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,operator,session.toString(),at(),at(),Timestamp.from(NOW.plusSeconds(43200)),at());owner.update("INSERT INTO privacy_case(id,requester_id,organization_id,country,kind,private_reason,created_at) VALUES(?,?,?,?,'REDACTION','PRIVATE-CASE-REASON',?)",source,subject,org,country,at());if(!role.equals("OWNER"))owner.update("UPDATE account_identity SET state='DEACTIVATED',revision=revision+1,updated_at=? WHERE id=?",at(),subject);});return new Fixture(source,org,country,subject,ownerId,new PrivateCaseReview.Actor(operator,session,"NATIVE"));}
 Timestamp at(){return Timestamp.from(clock.instant());}
 void guards(Fixture f){http.queryForList("SELECT id FROM organization WHERE id=? FOR UPDATE",f.organization());http.queryForList("SELECT id FROM account_identity WHERE id=? FOR UPDATE",f.actor().account());http.queryForList("SELECT id FROM application_session WHERE id=? FOR UPDATE",f.actor().session());}
 PrivateCaseReview.Access authorize(Fixture f){return httpTx.execute(s->{guards(f);return review.authorize(f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),f.actor(),new PrivateCaseReview.Context("Synthetic scope approval","SYN-SCOPE"));});}
 ScopedRedactions.Command command(Fixture f,UUID id){long revision=owner.queryForObject("SELECT coalesce((SELECT revision FROM privacy_redaction_fulfillment_metadata WHERE case_id=?),1)",Long.class,f.source());return new ScopedRedactions.Command(id,REVISIONS.encode("privacy/v1",f.source(),revision),"ACCOUNT_DISPLAY_NAME_V1",new ScopedRedactions.References("SYN-REQUESTER","SYN-LEGAL","SYN-CONTAINED","SYN-RETAINED"),new PrivateCaseReview.Context("Synthetic scope approval","SYN-SCOPE"));}
 ScopedRedactions.View approve(Fixture f,ScopedRedactions.Command c){var a=authorize(f);return httpTx.execute(s->{guards(f);return service.approve(a,c);});}
 ScopedRedactions.View status(Fixture f,UUID id){return httpTx.execute(s->{guards(f);return service.read(f.actor(),f.source(),id);});}
 static class Store implements IndependentObjects {
  final ConcurrentHashMap<Key,byte[]> values=new ConcurrentHashMap<>();boolean failIntent,failCompletion,loseWrite;Runnable afterIntent;
  public boolean create(Key k,byte[] b){IndependentEvidence.outside();if(failIntent&&k.family()==Family.DELETION_INTENT||failCompletion&&k.family()==Family.DELETION_COMPLETION)throw new EvidenceFailure("EVIDENCE_UNAVAILABLE");boolean result=values.putIfAbsent(k,b.clone())==null;if(k.family()==Family.DELETION_INTENT&&afterIntent!=null){var callback=afterIntent;afterIntent=null;callback.run();}if(loseWrite){loseWrite=false;throw new EvidenceFailure("EVIDENCE_UNAVAILABLE");}return result;}
  public Optional<byte[]> read(Key k){IndependentEvidence.outside();return Optional.ofNullable(values.get(k)).map(byte[]::clone);}public Page list(Family f,int n,Key a){throw new UnsupportedOperationException();}
 }
 IndependentEvidence evidence(Store s){return new IndependentEvidence(s,Map.of("v1",new byte[32]),"v1",List.of());}
 ScopedRedactionWorker worker(IndependentEvidence e){return new ScopedRedactionWorker(executor,new DataSourceTransactionManager(executor.getDataSource()),e,clock,ids,"SYNTHETIC","SYN-SCOPED");}
 String name(Fixture f){return owner.queryForObject("SELECT display_name FROM account_identity WHERE id=?",String.class,f.subject());}

 List<CaseDispositions.Item> retained(boolean pending){return CaseDispositions.FAMILIES.stream().map(f->new CaseDispositions.Item(f,f.equals("ADDITIONAL_SCOPE")?(pending?"PENDING":"REVIEWED_NO_ADDITIONAL_SCOPE"):"RETAINED",null,"SYN-REVIEW")).toList();}
 CaseDispositions.Command disposition(Fixture f,UUID id,boolean resolve,List<CaseDispositions.Item> items){long revision=owner.queryForObject("SELECT coalesce((SELECT revision FROM privacy_redaction_fulfillment_metadata WHERE case_id=?),1)",Long.class,f.source());return new CaseDispositions.Command(id,REVISIONS.encode("privacy/v1",f.source(),revision),items,resolve,resolve,new ScopedRedactions.References("SYN-REQUESTER","SYN-LEGAL","SYN-CONTAINED","SYN-RETAINED"),new PrivateCaseReview.Context("Synthetic scope disposition","SYN-DISPOSITION"));}
 CaseDispositions.View record(Fixture f,CaseDispositions.Command c){var access=authorize(f);return httpTx.execute(t->{guards(f);return dispositions.record(access,c);});}
 CaseDispositions.View readDisposition(Fixture f,UUID id){return httpTx.execute(t->{guards(f);return dispositions.read(f.actor(),f.source(),id);});}
 @Test void reviewedRetainedScopeResolvesBothCountriesWithoutAnErasureClaim(){for(String country:List.of("RS","BA"))for(String type:List.of("BUYER","VENDOR")){var f=fixture(country,type,"ADMIN");UUID id=ids.next();var command=disposition(f,id,true,retained(false));String before=name(f);var original=record(f,command);assertThat(original.state()).isEqualTo("COMPLETED");assertThat(original.assistedReviewResolved()).isTrue();assertThat(original.allDataErased()).isFalse();assertThat(name(f)).isEqualTo(before);assertThat(record(f,command)).isEqualTo(original);assertThat(readDisposition(f,id)).isEqualTo(original);assertThat(owner.queryForObject("SELECT state FROM privacy_redaction_fulfillment_metadata WHERE case_id=?",String.class,f.source())).isEqualTo("COMPLETED");assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_disposition WHERE case_id=?",Integer.class,f.source())).isEqualTo(1);assertThatThrownBy(()->approve(f,command(f,ids.next()))).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("CASE_CLOSED");}}
 @Test void pendingReviewAdvancesRevisionAndRequiresExplicitFinalReview(){var f=fixture("BA","BUYER","ADMIN");var pending=record(f,disposition(f,ids.next(),false,retained(true)));assertThat(pending.state()).isEqualTo("REVIEWING");assertThat(pending.assistedReviewResolved()).isFalse();var finished=record(f,disposition(f,ids.next(),true,retained(false)));assertThat(finished.state()).isEqualTo("COMPLETED");assertThat(finished.revision()).isNotEqualTo(pending.revision());assertThat(readDisposition(f,pending.id())).isEqualTo(pending);assertThat(owner.queryForObject("SELECT revision FROM privacy_redaction_fulfillment_metadata WHERE case_id=?",Long.class,f.source())).isEqualTo(3);}
 @Test void unresolvedMissingDuplicateAndUnboundFamiliesCannotResolveCase(){var f=fixture("RS","BUYER","ADMIN");for(String invalid:List.of("pending","missing","duplicate","unbound")){var items=new ArrayList<>(retained(false));if(invalid.equals("pending"))items.set(0,new CaseDispositions.Item("CURRENT_DISPLAY_NAME","PENDING",null,"SYN-REVIEW"));if(invalid.equals("missing"))items.remove(0);if(invalid.equals("duplicate"))items.set(0,items.get(1));if(invalid.equals("unbound"))items.set(0,new CaseDispositions.Item("CURRENT_DISPLAY_NAME","APPLIED",ids.next(),"SYN-REVIEW"));assertThatThrownBy(()->record(f,disposition(f,ids.next(),true,items))).isInstanceOf(PrivacyFailure.class);}assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_disposition WHERE case_id=?",Integer.class,f.source())).isZero();}
 @Test void currentCaseRevisionAndNaturalIdentityProtectOriginalReview(){var f=fixture("RS","VENDOR","ADMIN");var first=disposition(f,ids.next(),false,retained(true));var stale=disposition(f,ids.next(),true,retained(false));var original=record(f,first);assertThatThrownBy(()->record(f,stale)).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("REVISION_MISMATCH");var mismatch=new CaseDispositions.Command(first.id(),first.expectedCaseRevision(),retained(false),true,true,first.references(),first.context());assertThatThrownBy(()->record(f,mismatch)).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("IDEMPOTENCY_MISMATCH");assertThat(record(f,first)).isEqualTo(original);}
 @Test void pendingScopedWorkBlocksTerminalReviewButCanBeRecordedAsPending(){var f=fixture("BA","VENDOR","ADMIN");UUID job=ids.next();approve(f,command(f,job));assertThatThrownBy(()->record(f,disposition(f,ids.next(),true,retained(false)))).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("WORK_PENDING");assertThat(record(f,disposition(f,ids.next(),false,retained(true))).state()).isEqualTo("REVIEWING");}
 @Test void appliedHistoricalScopeAlsoProvesCurrentDisplayNameButNeverAnotherCase(){var f=fixture("RS","BUYER","ADMIN");var c=command(f,ids.next());var named=new ScopedRedactions.Command(c.id(),c.expectedCaseRevision(),"REQUESTER_NAMES_V1",c.references(),c.context());approve(f,named);assertThat(worker(evidence(new Store())).run(named.id(),false).state()).isEqualTo("COMPLETED");var items=new ArrayList<>(retained(false));for(int i=0;i<2;i++)items.set(i,new CaseDispositions.Item(CaseDispositions.FAMILIES.get(i),"APPLIED",named.id(),"SYN-REVIEW"));var other=fixture("RS","BUYER","ADMIN");assertThatThrownBy(()->record(other,disposition(other,ids.next(),true,items))).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("ACTION_NOT_COMPLETED");assertThat(record(f,disposition(f,ids.next(),true,items)).state()).isEqualTo("COMPLETED");}
 @Test void actualDeferredCommitFailureRollsBackDispositionAndItsAudit(){var f=fixture("RS","BUYER","ADMIN");var command=disposition(f,ids.next(),true,retained(false));owner.execute("CREATE FUNCTION synthetic_disposition_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='PRIVACY_DISPOSITION_RECORDED' THEN RAISE EXCEPTION 'Synthetic disposition commit failure';END IF;RETURN NULL;END $$");owner.execute("CREATE CONSTRAINT TRIGGER tr_synthetic_disposition_failure AFTER INSERT ON audit_event DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION synthetic_disposition_failure()");try{assertThatThrownBy(()->record(f,command)).isInstanceOf(org.springframework.transaction.TransactionSystemException.class);}finally{owner.execute("DROP TRIGGER tr_synthetic_disposition_failure ON audit_event");owner.execute("DROP FUNCTION synthetic_disposition_failure()");}assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_disposition WHERE case_id=?",Integer.class,f.source())).isZero();assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='PRIVACY_DISPOSITION_RECORDED'",Integer.class,f.source())).isZero();assertThat(record(f,command).state()).isEqualTo("COMPLETED");}
 @Test void twoConcurrentIdenticalReviewsCommitOneOriginalOutcome()throws Exception{var f=fixture("BA","BUYER","ADMIN");var command=disposition(f,ids.next(),true,retained(false));var one=authorize(f);var two=authorize(f);var start=new CountDownLatch(1);try(var threads=Executors.newFixedThreadPool(2)){var a=threads.submit(()->{start.await();return httpTx.execute(t->{guards(f);return dispositions.record(one,command);});});var b=threads.submit(()->{start.await();return httpTx.execute(t->{guards(f);return dispositions.record(two,command);});});start.countDown();var first=a.get(15,TimeUnit.SECONDS);assertThat(b.get(15,TimeUnit.SECONDS)).isEqualTo(first);}assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_disposition WHERE case_id=?",Integer.class,f.source())).isEqualTo(1);assertThat(owner.queryForObject("SELECT count(*) FROM audit_event WHERE resource_id=? AND action='PRIVACY_DISPOSITION_RECORDED'",Integer.class,f.source())).isEqualTo(1);}
 @Test void lateHoldAndQualificationRevocationRejectTerminalReview(){for(String blocker:List.of("hold","qualification")){var f=fixture("BA","VENDOR","ADMIN");var command=disposition(f,ids.next(),true,retained(false));var access=authorize(f);@SuppressWarnings("unchecked") ObjectProvider<ResourceRevisions> r=mock(ObjectProvider.class);when(r.getObject()).thenReturn(REVISIONS);var holds=new JdbcRetentionHolds(owner,new JdbcPrivateCaseReview(owner,clock,ids),clock,ids,r);UUID hold=ids.next();RetentionHolds.View[] held=new RetentionHolds.View[1];if(blocker.equals("hold"))held[0]=ownerTx.execute(t->holds.activate(f.actor(),f.source(),new PrivateCaseReview.Target(f.organization(),f.country()),hold,new RetentionHolds.Context("Synthetic late hold","SYN-HOLD")));else ownerTx.executeWithoutResult(t->{owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-REVOKE'");owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",f.actor().account());});try{assertThatThrownBy(()->httpTx.execute(t->{guards(f);return dispositions.record(access,command);})).isInstanceOf(PrivacyFailure.class);assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_disposition WHERE case_id=?",Integer.class,f.source())).isZero();}finally{if(held[0]!=null)ownerTx.executeWithoutResult(t->holds.release(f.actor(),f.source(),hold,held[0].revision(),new RetentionHolds.Context("Synthetic release","SYN-RELEASE")));}}}
 @Test void sourceActionMustBeCompletedAndStillMatchCurrentSupportedField(){var f=fixture("RS","VENDOR","ADMIN");var command=command(f,ids.next());approve(f,command);var store=new Store();store.failCompletion=true;var e=evidence(store);assertThatThrownBy(()->worker(e).run(command.id(),false)).isInstanceOf(EvidenceFailure.class);var items=new ArrayList<>(retained(false));items.set(0,new CaseDispositions.Item("CURRENT_DISPLAY_NAME","APPLIED",command.id(),"SYN-REVIEW"));assertThatThrownBy(()->record(f,disposition(f,ids.next(),true,items))).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("ACTION_NOT_COMPLETED");store.failCompletion=false;assertThat(worker(e).run(command.id(),true).state()).isEqualTo("COMPLETED");owner.update("UPDATE account_identity SET display_name='Changed',revision=revision+1 WHERE id=?",f.subject());assertThatThrownBy(()->record(f,disposition(f,ids.next(),true,items))).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("STALE_PLAN");}

 @Test void pendingReviewAllowsSubsequentScopedWorkAndClosedCaseKeepsOriginalReplay(){var f=fixture("BA","VENDOR","ADMIN");record(f,disposition(f,ids.next(),false,retained(true)));var c=command(f,ids.next());var original=approve(f,c);assertThat(worker(evidence(new Store())).run(c.id(),false).state()).isEqualTo("COMPLETED");var items=new ArrayList<>(retained(false));items.set(0,new CaseDispositions.Item("CURRENT_DISPLAY_NAME","APPLIED",c.id(),"SYN-REVIEW"));assertThat(record(f,disposition(f,ids.next(),true,items)).state()).isEqualTo("COMPLETED");assertThat(approve(f,c)).isEqualTo(original);assertThat(owner.queryForObject("SELECT revision FROM privacy_redaction_fulfillment_metadata WHERE case_id=?",Long.class,f.source())).isEqualTo(7);}
 @Test void soleOwnerCannotBeTerminallyResolvedAndRevokedOperatorCannotReadOrReplay(){var ownerFixture=fixture("RS","BUYER","OWNER");assertThatThrownBy(()->record(ownerFixture,disposition(ownerFixture,ids.next(),true,retained(false)))).isInstanceOf(PrivacyFailure.class).extracting(v->((PrivacyFailure)v).code()).isEqualTo("OWNER_PROTECTED");var f=fixture("RS","BUYER","ADMIN");var c=disposition(f,ids.next(),true,retained(false));record(f,c);ownerTx.executeWithoutResult(t->{owner.execute("SET LOCAL narudzbine.operator_change_reference='SYN-REVOKE'");owner.update("UPDATE privacy_operator SET enabled=false,revision=revision+1 WHERE account_id=?",f.actor().account());});assertThatThrownBy(()->readDisposition(f,c.id())).isInstanceOf(PrivacyFailure.class);assertThatThrownBy(()->record(f,c)).isInstanceOf(PrivacyFailure.class);}
 @Test void runtimeCannotMutateDispositionOrAttachItsPrivilegedTriggers(){for(var jdbc:List.of(http,executor))for(String sql:List.of("SELECT * FROM privacy_case_disposition","UPDATE privacy_case_disposition SET resolve_case=true","DELETE FROM privacy_case_disposition","TRUNCATE privacy_case_disposition","SELECT protect_case_disposition()","SELECT block_completed_case_new_scope()"))assertThatThrownBy(()->jdbc.execute(sql)).isInstanceOf(org.springframework.dao.DataAccessException.class);}

 @Test void actualStartupGateRejectsRawCaseReadsAndWorkerAcknowledgementPrivilege(){var env=new org.springframework.mock.env.MockEnvironment().withProperty("identity.http.enabled","true");new CaseDispositionConfiguration().caseDispositionPrivilegeGate(http,env);for(String permission:List.of("SELECT ON privacy_case_disposition","EXECUTE ON FUNCTION acknowledge_scoped_redaction(uuid,text,text,integer,text,timestamptz)")){owner.execute("GRANT "+permission+" TO scoped_http");try{assertThatThrownBy(()->new CaseDispositionConfiguration().caseDispositionPrivilegeGate(http,env)).isInstanceOf(IllegalStateException.class).hasMessage("Case dispositions require isolated projection/action grants");}finally{owner.execute("REVOKE "+permission+" FROM scoped_http");}}new CaseDispositionConfiguration().caseDispositionPrivilegeGate(http,env);}

 @Test void sevenDayReplayUsesUtcAcrossActualDstAndReturnsOnlyAuthorizedResource(){for(String country:List.of("RS","BA")){var f=fixture(country,"BUYER","ADMIN");var c=disposition(f,ids.next(),true,retained(false));var original=record(f,c);assertThat(NOW.atZone(ZoneId.of("Europe/Belgrade")).plusDays(7).toInstant()).isNotEqualTo(NOW.plusSeconds(604800));clock.at=NOW.plusSeconds(604799);UUID session=ids.next();owner.update("INSERT INTO application_session(id,account_id,transport,token_hash,device_label,created_at,last_qualified_activity_at,absolute_expires_at,auth_at,auth_method_type,credential_generation,security_epoch) VALUES(?,?,'NATIVE',sha256(convert_to(?,'UTF8')),'Synthetic',?,?,?,?,'PASSWORD',0,0)",session,f.actor().account(),session.toString(),at(),at(),Timestamp.from(clock.instant().plusSeconds(43200)),at());var refreshed=new Fixture(f.source(),f.organization(),f.country(),f.subject(),f.owner(),new PrivateCaseReview.Actor(f.actor().account(),session,"NATIVE"));try{assertThat(record(refreshed,c)).isEqualTo(original);clock.at=NOW.plusSeconds(604800);assertThatThrownBy(()->record(refreshed,c)).isInstanceOf(PrivacyFailure.class).satisfies(v->{assertThat(((PrivacyFailure)v).code()).isEqualTo("REPLAY_EXPIRED");assertThat(((PrivacyFailure)v).resource()).isEqualTo(c.id());});assertThat(readDisposition(refreshed,c.id())).isEqualTo(original);assertThat(owner.queryForObject("SELECT count(*) FROM privacy_case_disposition WHERE case_id=?",Integer.class,f.source())).isEqualTo(1);}finally{clock.at=NOW;}}}

